QRect Overlay::sourceRect()const{return QRect(qRound(m_selection.x()*m_image.width()/double(width())),qRound(m_selection.y()*m_image.height()/double(height())),qRound(m_selection.width()*m_image.width()/double(width())),qRound(m_selection.height()*m_image.height()/double(height()))).intersected(m_image.rect());}
void Overlay::prepareEditor(){m_capture={};m_capture.image=m_image.copy(sourceRect());m_capture.image.setDevicePixelRatio(1);m_editor->setGeometry(m_selection);m_editor->setCapture(&m_capture);m_editor->setTool(0);m_editor->setAttribute(Qt::WA_TransparentForMouseEvents);m_editor->show();m_toolbar->raise();}
void Overlay::placeToolbar(){m_toolbar->adjustSize();int x=qBound(0,m_selection.right()-m_toolbar->width(),qMax(0,width()-m_toolbar->width()));int y=m_selection.bottom()+12;if(y+m_toolbar->height()>height())y=qMax(0,m_selection.top()-m_toolbar->height()-12);m_toolbar->move(x,y);m_toolbar->show();reveal(m_toolbar,120);}
