void Overlay::mousePressEvent(QMouseEvent*e){m_cursor=e->position().toPoint();if(e->button()==Qt::MiddleButton&&m_selection.isValid()){commit(3);return;}if(e->button()==Qt::RightButton){if(m_editor->tool()!=0){m_editor->setTool(0);m_editor->setAttribute(Qt::WA_TransparentForMouseEvents);m_drawTools->hide();placeToolbar();setFocus();}else close();return;}if(e->button()!=Qt::LeftButton)return;m_toolbar->hide();m_editor->hide();m_start=m_cursor;m_last=m_cursor;m_initial=m_selection;m_resize=-1;m_moving=false;if(m_selection.isValid()){auto r=m_selection;QVector<QPoint> handles={r.topLeft(),r.topRight(),r.bottomLeft(),r.bottomRight(),QPoint(r.center().x(),r.top()),QPoint(r.center().x(),r.bottom()),QPoint(r.left(),r.center().y()),QPoint(r.right(),r.center().y())};for(int i=0;i<handles.size();i++)if(QLineF(handles[i],m_cursor).length()<8)m_resize=i;if(m_resize<0&&m_selection.contains(m_cursor))m_moving=true;}m_dragging=true;if(!m_moving&&m_resize<0)m_selection={};update();}
void Overlay::mouseMoveEvent(QMouseEvent*e){m_cursor=e->position().toPoint();if(m_dragging){if(m_moving){m_selection=m_initial.translated(m_cursor-m_start);m_selection.moveLeft(qBound(0,m_selection.left(),width()-m_selection.width()));m_selection.moveTop(qBound(0,m_selection.top(),height()-m_selection.height()));}else if(m_resize>=0){auto r=m_initial;auto d=m_cursor-m_start;if(m_resize==0||m_resize==2||m_resize==6)r.setLeft(r.left()+d.x());if(m_resize==1||m_resize==3||m_resize==7)r.setRight(r.right()+d.x());if(m_resize==0||m_resize==1||m_resize==4)r.setTop(r.top()+d.y());if(m_resize==2||m_resize==3||m_resize==5)r.setBottom(r.bottom()+d.y());m_selection=r.normalized().intersected(rect());}else{if(m_space)m_start+=m_cursor-m_last;m_selection=QRect(m_start,m_cursor).normalized().intersected(rect());}m_last=m_cursor;}update();}
